import React, { useEffect, useState, useRef } from 'react';
import { FaPlane } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';
import { createNoise2D } from 'simplex-noise';

const DecorativePlanes = () => {
  const { theme } = useTheme();
  const [planes, setPlanes] = useState([]);
  const noise2D = useRef(createNoise2D());
  const frameRef = useRef(0);
  const animationFrameRef = useRef();

  const createPlane = (id) => ({
    id,
    size: 20 + Math.random() * 15,
    angle: Math.random() * Math.PI * 2,
    speed: 0.1 + Math.random() * 0.2,
    turnStrength: 0.005 + Math.random() * 0.01,
    noiseSeed: Math.random() * 1000,
    noiseTimeFactor: 0.001,
    x: Math.random() * 100,
    y: Math.random() * 100
  });

  const updatePlane = (plane) => {
    // Calculate time for noise
    const currentTimeForNoise = frameRef.current * plane.noiseTimeFactor;
    
    // Calculate angle change using noise
    const noiseInput = plane.noiseSeed + currentTimeForNoise;
    const noiseOutput = noise2D.current(noiseInput, 0);
    const normalizedNoise = (noiseOutput - 0.5) * 2;
    const angleChange = normalizedNoise * plane.turnStrength;
    
    // Update angle
    const newAngle = (plane.angle + angleChange + Math.PI * 2) % (Math.PI * 2);
    
    // Update position
    const deltaX = Math.cos(newAngle) * plane.speed;
    const deltaY = Math.sin(newAngle) * plane.speed;
    const newX = plane.x + deltaX;
    const newY = plane.y + deltaY;
    
    // Screen wrapping
    const wrappedX = newX < -plane.size ? 100 + plane.size : 
                    newX > 100 + plane.size ? -plane.size : newX;
    const wrappedY = newY < -plane.size ? 100 + plane.size : 
                    newY > 100 + plane.size ? -plane.size : newY;

    return {
      ...plane,
      angle: newAngle,
      x: wrappedX,
      y: wrappedY
    };
  };

  useEffect(() => {
    // Initialize planes
    const initialPlanes = Array.from({ length: 8 }, (_, index) => createPlane(index));
    setPlanes(initialPlanes);

    // Animation loop
    const animate = () => {
      frameRef.current++;
      setPlanes(currentPlanes => 
        currentPlanes.map(plane => updatePlane(plane))
      );
      animationFrameRef.current = requestAnimationFrame(animate);
    };

    animationFrameRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  return (
    <div 
      className="fixed inset-0 pointer-events-none overflow-hidden" 
      style={{ 
        zIndex: 0,
        backgroundColor: 'rgba(0,0,0,0.02)'
      }}
    >
      {planes.map(plane => (
        <div
          key={plane.id}
          className="absolute"
          style={{
            left: `${plane.x}%`,
            top: `${plane.y}%`,
            transform: `rotate(${plane.angle * (180 / Math.PI)}deg)`,
            transition: 'transform 0.1s linear',
            opacity: 0.4,
            color: theme.primary,
            filter: 'drop-shadow(0 0 2px rgba(0,0,0,0.2))'
          }}
        >
          <FaPlane size={plane.size} />
        </div>
      ))}
    </div>
  );
};

export default DecorativePlanes;
